import React, { useContext, useEffect, useState } from 'react';
import { FormattedMessage } from 'react-intl';

import { CodeIcon, CodeOffIcon } from '@dynatrace/strato-icons';

import { useTableUserActionsContext } from './useTableUserActionsContext.js';
import { Menu } from '../../../../navigation/menu/Menu.js';
import { DataTableContext } from '../../../contexts/DataTableContext.js';
import { dataTableMessages } from '../../../DataTable/messages.js';
import { ColumnMinInstance } from '../../../types/internal-table-types.js';
import { useUserActionsActions } from '../actions.js';

export const FontStyle = () => {
  const tableActionContext = useTableUserActionsContext();
  const { variant, onDataTableColumnFontStyleChange } =
    useContext(DataTableContext);
  const [fontStyle, setFontStyle] = useState<'text' | 'code'>('text');

  if (tableActionContext === null) {
    return null;
  }
  const { column, dispatch } = tableActionContext;

  // update column actions menu labels/icons appropriately when column or table font style changes
  // eslint-disable-next-line react-hooks/rules-of-hooks
  useEffect(() => {
    setFontStyle(
      column.fontStyle === undefined
        ? variant.fontStyle === 'code'
          ? 'code'
          : 'text'
        : column.fontStyle,
    );
  }, [column.fontStyle, variant.fontStyle]); // update only when column or table font style changes

  return (
    <Menu.Item
      onSelect={() => {
        column.fontStyle = fontStyle === 'text' ? 'code' : 'text';
        setFontStyle(column.fontStyle);
        if (onDataTableColumnFontStyleChange) {
          onDataTableColumnFontStyleChange(column as ColumnMinInstance);
        }
        dispatch({
          type: useUserActionsActions.columnPropertiesChanged,
        });
      }}
    >
      {fontStyle === 'text' && (
        <Menu.ItemIcon>
          <CodeIcon />
        </Menu.ItemIcon>
      )}
      {fontStyle === 'code' && (
        <Menu.ItemIcon>
          <CodeOffIcon />
        </Menu.ItemIcon>
      )}

      {fontStyle === 'text' ? (
        <FormattedMessage {...dataTableMessages.fontStyleCodeLabel} />
      ) : (
        <FormattedMessage {...dataTableMessages.fontStyleTextLabel} />
      )}
    </Menu.Item>
  );
};

FontStyle['displayName'] = 'TableUserActions.FontStyle';
